import{_ as n,f as a,o as e,aq as o}from"./chunks/framework.BvNt3gUw.js";const h=JSON.parse('{"title":"Service Container","description":"","frontmatter":{},"headers":[],"relativePath":"architecture-concepts/service-container.md","filePath":"en/architecture-concepts/service-container.md","lastUpdated":1789895472000}'),l={name:"architecture-concepts/service-container.md"};function p(r,s,t,c,i,d){return e(),a("div",null,s[0]||(s[0]=[o(`<h1 id="service-container" tabindex="-1">Service Container <a class="header-anchor" href="#service-container" aria-label="Permalink to “Service Container”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>The Goravel service container is a powerful tool for managing class dependencies and performing dependency injection. It contains all the modules of Goravel, and allows you to bind your own services to container and resolve them when needed. The service container provides powerful support for third-party packages around Goravel.</p><h2 id="binding" tabindex="-1">Binding <a class="header-anchor" href="#binding" aria-label="Permalink to “Binding”">​</a></h2><h3 id="simple-bindings" tabindex="-1">Simple Bindings <a class="header-anchor" href="#simple-bindings" aria-label="Permalink to “Simple Bindings”">​</a></h3><p>Almost all of your service container bindings will be registered within <a href="./service-providers.html">service providers</a>. Within a service provider, you always have access to the container via the <code>app</code> parameter, then register a binding using the <code>Bind</code> method, passing the <code>key</code> that we wish to register along with a closure that returns an instance of the class:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package route</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">github.com/goravel/framework/contracts/foundation</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">const Binding </span><span style="color:#68747D;">=</span><span style="color:#68747D;"> &quot;goravel.route&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type ServiceProvider struct </span><span style="color:#68747D;">{}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">route </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Register</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Bind</span><span style="color:#68747D;">(</span><span style="color:#101820;">Binding</span><span style="color:#68747D;">,</span><span style="color:#101820;"> func</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> (</span><span style="color:#101820;">any</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">    return </span><span style="color:#0077B3;">NewRoute</span><span style="color:#68747D;">(</span><span style="color:#101820;">app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">MakeConfig</span><span style="color:#68747D;">()),</span><span style="color:#101820;"> nil</span></span>
<span class="line"><span style="color:#68747D;">  })</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">route </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>As mentioned, you will typically be interacting with the container within service providers; however, if you would like to interact with the container outside of a service provider, you may do so via the <code>App</code> facade:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">App</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Bind</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;key&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> func</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> (</span><span style="color:#101820;">any</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#68747D;">  ...</span></span>
<span class="line"><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="binding-a-singleton" tabindex="-1">Binding A Singleton <a class="header-anchor" href="#binding-a-singleton" aria-label="Permalink to “Binding A Singleton”">​</a></h3><p>The <code>Singleton</code> method binds a class or interface into the container that should only be resolved one time. Once a singleton binding is resolved, the same object instance will be returned on subsequent calls into the container:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Singleton</span><span style="color:#68747D;">(</span><span style="color:#101820;">key</span><span style="color:#68747D;">,</span><span style="color:#101820;"> func</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> (</span><span style="color:#101820;">any</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  return </span><span style="color:#0077B3;">NewGin</span><span style="color:#68747D;">(</span><span style="color:#101820;">app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">MakeConfig</span><span style="color:#68747D;">()),</span><span style="color:#101820;"> nil</span></span>
<span class="line"><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="binding-instances" tabindex="-1">Binding Instances <a class="header-anchor" href="#binding-instances" aria-label="Permalink to “Binding Instances”">​</a></h3><p>You may also bind an existing object instance into the container using the <code>Instance</code> method. The given instance will always be returned on subsequent calls into the container:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Instance</span><span style="color:#68747D;">(</span><span style="color:#101820;">key</span><span style="color:#68747D;">,</span><span style="color:#101820;"> instance</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="binding-with-parameter" tabindex="-1">Binding With Parameter <a class="header-anchor" href="#binding-with-parameter" aria-label="Permalink to “Binding With Parameter”">​</a></h3><p>If you need some extra parameters to construct the service provider, you can use the <code>BindWith</code> method to pass parameters to the closure:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">BindWith</span><span style="color:#68747D;">(</span><span style="color:#101820;">Binding</span><span style="color:#68747D;">,</span><span style="color:#101820;"> func</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">,</span><span style="color:#101820;"> parameters map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> (</span><span style="color:#101820;">any</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  return </span><span style="color:#0077B3;">NewRoute</span><span style="color:#68747D;">(</span><span style="color:#101820;">app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">MakeConfig</span><span style="color:#68747D;">()),</span><span style="color:#101820;"> nil</span></span>
<span class="line"><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="resolving" tabindex="-1">Resolving <a class="header-anchor" href="#resolving" aria-label="Permalink to “Resolving”">​</a></h2><h3 id="the-make-method" tabindex="-1">The <code>Make</code> Method <a class="header-anchor" href="#the-make-method" aria-label="Permalink to “The Make Method”">​</a></h3><p>You may use the <code>Make</code> method to resolve a class instance from the container. The <code>Make</code> method accepts the <code>key</code> you wish to resolve:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">instance</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Make</span><span style="color:#68747D;">(</span><span style="color:#101820;">key</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If you are outside of a service provider in a location of your code that does not have access to the <code>app</code> variable, you may use the <code>App</code> facade to resolve a class instance from the container:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">instance</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">App</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Make</span><span style="color:#68747D;">(</span><span style="color:#101820;">key</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="the-makewith-method" tabindex="-1">The <code>MakeWith</code> Method <a class="header-anchor" href="#the-makewith-method" aria-label="Permalink to “The MakeWith Method”">​</a></h3><p>If some of your class&#39;s dependencies are not resolvable via the container, you may inject them by passing them as an associative array into the <code>MakeWith</code> method, corresponding to the <code>BindWith</code> binding method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">instance</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">MakeWith</span><span style="color:#68747D;">(</span><span style="color:#101820;">key</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;id&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> 1})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="other-methods" tabindex="-1">Other Methods <a class="header-anchor" href="#other-methods" aria-label="Permalink to “Other Methods”">​</a></h3><p>The framework provides some convenient methods to quickly resolve various facades: <code>MakeArtisan</code>, <code>MakeAuth</code>, etc.</p>`,29)]))}const u=n(l,[["render",p]]);export{h as __pageData,u as default};
